1	export type Item = {
2	  type: string;
3	};
4	
5	export type Step = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Customer = {
11	  yearsWithMHPCO: number;
12	};
13	
14	export type Scenario = {
15	  customer: Customer;
16	  steps: Step[];
17	};
18	
19	export type QuoteResult = {
20	  premium: number;
21	};
22	
23	export type ScenarioResult = {
24	  results: QuoteResult[];
25	};
26	
27	const PROCESSING_FEE = 5;
28	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	};
35	
36	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
37	
38	const policyBasePremium = (items: Item[]): number =>
39	  items.reduce((total, item) => total + basePremiumOf(item), 0);
40	
41	const quote = (step: Step): QuoteResult => {
42	  const basePremium = policyBasePremium(step.items);
43	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
44	
45	  return { premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE };
46	};
47	
48	export const runScenario = (scenario: Scenario): ScenarioResult => ({
49	  results: scenario.steps.map(quote),
50	});
51

